<template>
  <div class="page"><div class="page-heading"><div><h1>工作台</h1><p>今天也要高效完成采购工作，{{ auth.user.nickname || auth.user.username || '管理员' }}。</p></div><el-button type="primary" :icon="Plus" @click="router.push('/requests')">新建采购申请</el-button></div>
    <div class="stat-grid"><div class="stat-card blue"><div class="stat-icon"><Document /></div><div><span>采购申请总数</span><strong>{{ stats.totalRequests }}</strong><small>较上月 <em>+12.5%</em></small></div></div><div class="stat-card orange"><div class="stat-icon"><Clock /></div><div><span>待审批申请</span><strong>{{ stats.pendingRequests }}</strong><small>需要及时处理</small></div></div><div class="stat-card green"><div class="stat-icon"><CircleCheck /></div><div><span>本月已完成</span><strong>{{ stats.approvedRequests }}</strong><small>较上月 <em>+8.2%</em></small></div></div><div class="stat-card red"><div class="stat-icon"><Warning /></div><div><span>库存预警</span><strong>{{ stats.inventoryAlerts }}</strong><small>请及时补充库存</small></div></div></div>
    <div class="dashboard-columns"><el-card class="panel-card workflow-card"><template #header><div class="card-header"><span>采购流程概览</span><el-button link type="primary" @click="router.push('/requests')">查看全部 <el-icon><ArrowRight /></el-icon></el-button></div></template><div class="workflow"><div v-for="(step, index) in workflow" :key="step.label" class="workflow-step"><div class="workflow-icon" :class="step.color"><el-icon><component :is="step.icon" /></el-icon></div><strong>{{ step.value }}</strong><span>{{ step.label }}</span><div v-if="index < workflow.length - 1" class="workflow-line"></div></div></div><div class="progress-row"><span>本月采购完成率</span><el-progress :percentage="78" :stroke-width="9" color="#2563eb" /><b>78%</b></div></el-card><el-card class="panel-card quick-card"><template #header><div class="card-header"><span>快捷入口</span></div></template><div class="quick-grid"><button v-for="item in quickItems" :key="item.label" @click="router.push(item.path)"><span :class="item.color"><el-icon><component :is="item.icon" /></el-icon></span><em>{{ item.label }}</em></button></div></el-card></div>
    <el-card class="panel-card recent-card"><template #header><div class="card-header"><span>最近采购申请</span><el-button link type="primary" @click="router.push('/requests')">查看更多</el-button></div></template><el-table :data="recent" stripe><el-table-column prop="requestNo" label="申请编号" width="180" /><el-table-column prop="reason" label="采购事由" min-width="260" show-overflow-tooltip /><el-table-column prop="applicant" label="申请人" width="120" /><el-table-column prop="amount" label="金额" width="130"><template #default="{ row }">¥ {{ Number(row.amount || 0).toLocaleString() }}</template></el-table-column><el-table-column prop="status" label="状态" width="120"><template #default="{ row }"><StatusTag :status="row.status" /></template></el-table-column><el-table-column prop="createTime" label="申请时间" width="180" /></el-table></el-card>
  </div>
</template>
<script setup>
import { onMounted, reactive, ref } from 'vue'; import { useRouter } from 'vue-router'; import { useAuthStore } from '../stores/auth'; import { api } from '../api'; import StatusTag from '../components/StatusTag.vue'; import { Plus, Document, Clock, CircleCheck, Warning, ArrowRight, Checked, Shop, Tickets, Box } from '@element-plus/icons-vue'
const router = useRouter(); const auth = useAuthStore(); const stats = reactive({ totalRequests: 0, pendingRequests: 0, approvedRequests: 0, inventoryAlerts: 0 }); const recent = ref([])
const workflow = [{ label: '待审批', value: 3, icon: Clock, color: 'orange' }, { label: '审批通过', value: 12, icon: Checked, color: 'blue' }, { label: '采购中', value: 8, icon: Tickets, color: 'purple' }, { label: '已完成', value: 28, icon: CircleCheck, color: 'green' }]; const quickItems = [{ label: '采购申请', path: '/requests', icon: Document, color: 'blue' }, { label: '审批中心', path: '/approvals', icon: Checked, color: 'orange' }, { label: '供应商', path: '/suppliers', icon: Shop, color: 'purple' }, { label: '库存管理', path: '/inventory', icon: Box, color: 'green' }]
onMounted(async () => { const data = await api.dashboard(); Object.assign(stats, data?.data || data || {}); const req = await api.requests(); recent.value = (req?.records || req?.data?.records || []).slice(0, 5) })
</script>
